import shutil, re, openpyxl
from datetime import datetime, date, timedelta

shutil.copy(INIT, OUT)
vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)
s1v = vals["Sheet1"]
s2v = vals["Sheet2"]
s1 = wb["Sheet1"]

def norm_date(v):
    if v is None or isinstance(v, bool):
        return None
    if isinstance(v, datetime):
        return v.date().isoformat()
    if isinstance(v, date):
        return v.isoformat()
    if isinstance(v, (int, float)):
        if 20000 < v < 50000:
            return (datetime(1899, 12, 30) + timedelta(days=float(v))).date().isoformat()
        return str(v)
    s = str(v).strip()
    if not s:
        return None
    try:
        return datetime.fromisoformat(s.replace(" ", "T")).date().isoformat()
    except Exception:
        pass
    for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d", "%d/%m/%Y", "%m/%d/%Y", "%d-%m-%Y", "%m-%d-%Y"):
        try:
            return datetime.strptime(s, fmt).date().isoformat()
        except Exception:
            pass
    return s

def norm_meet(v):
    if v is None:
        return None
    s = str(v).strip().upper()
    return s or None

def norm_race(v):
    if v is None or isinstance(v, bool):
        return None
    if isinstance(v, (int, float)):
        if float(v).is_integer():
            return int(v)
        return float(v)
    s = str(v).strip()
    if not s:
        return None
    m = re.search(r"\d+", s)
    if m:
        return int(m.group())
    return s

def norm_num(v):
    if v is None or isinstance(v, bool):
        return None
    if isinstance(v, (int, float)):
        if float(v).is_integer():
            return int(v)
        return float(v)
    s = str(v).strip()
    if not s:
        return None
    try:
        f = float(s)
        if f.is_integer():
            return int(f)
        return f
    except Exception:
        return None

def clean_top(v):
    if v is None:
        return None
    if isinstance(v, str):
        s = v.strip()
        return s if s else None
    return v

map_date = {}
map_nodate = {}
for r in range(2, s2v.max_row + 1):
    meet = norm_meet(s2v.cell(row=r, column=4).value)
    race = norm_race(s2v.cell(row=r, column=8).value)
    if meet is None or race is None:
        continue
    d = norm_date(s2v.cell(row=r, column=2).value)
    top = clean_top(s2v.cell(row=r, column=9).value)
    res = [norm_num(s2v.cell(row=r, column=c).value) for c in (10, 11, 12, 13)]
    if d is not None:
        map_date.setdefault((d, meet, race), (top, res))
    map_nodate.setdefault((meet, race), (top, res))

max_row = max(s1v.max_row, s1.max_row, 370)
filled_h = 0
filled_i = 0
for r in range(2, max_row + 1):
    meet = norm_meet(s1v.cell(row=r, column=4).value)
    race = norm_race(s1v.cell(row=r, column=7).value)
    d = norm_date(s1v.cell(row=r, column=2).value)
    entry = None
    if d is not None:
        entry = map_date.get((d, meet, race))
    if entry is None:
        entry = map_nodate.get((meet, race))
    if entry is None:
        s1.cell(row=r, column=8).value = None
        s1.cell(row=r, column=9).value = None
        continue
    top, res = entry
    s1.cell(row=r, column=8).value = top
    if top is not None:
        filled_h += 1
    tab = norm_num(s1v.cell(row=r, column=10).value)
    rank = None
    if tab is not None:
        for idx, val in enumerate(res, start=1):
            if val is not None and val == tab:
                rank = idx
                break
    s1.cell(row=r, column=9).value = rank
    if rank is not None:
        filled_i += 1

wb.save(OUT)
print("max_row", max_row, "filled_h", filled_h, "filled_i", filled_i)
for r in (2, 3, 4, 5, 8, 16, 19, 366, 370):
    if r <= max_row:
        print(r, repr(s1.cell(row=r, column=8).value), repr(s1.cell(row=r, column=9).value))
